import { createMiddleware } from "@tanstack/react-start";
import { getRequest } from "@tanstack/react-start/server";
import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";

function isNewSupabaseApiKey(value: string): boolean {
  return value.startsWith("sb_publishable_") || value.startsWith("sb_secret_");
}

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return (input, init) => {
    const headers = new Headers(
      typeof Request !== "undefined" && input instanceof Request
        ? input.headers
        : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) =>
        headers.set(key, value),
      );
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    if (
      isNewSupabaseApiKey(supabaseKey) &&
      headers.get("Authorization") === `Bearer ${supabaseKey}`
    ) {
      headers.delete("Authorization");
    }

    headers.set("apikey", supabaseKey);
    return fetch(input, { ...init, headers });
  };
}

export const requireSupabaseAuth = createMiddleware({
  type: "function",
}).server(async ({ next }) => {
  const SUPABASE_URL =
    process.env.SUPABASE_URL || "https://placeholder-myaipro.supabase.co";
  const SUPABASE_PUBLISHABLE_KEY =
    process.env.SUPABASE_PUBLISHABLE_KEY || "sb_publishable_placeholder";

  let request: Request | undefined;
  try {
    request = getRequest();
  } catch {
    // getRequest may throw outside active request context
  }

  const authHeader = request?.headers ? request.headers.get("authorization") : null;
  const token = authHeader?.startsWith("Bearer ")
    ? authHeader.replace("Bearer ", "")
    : undefined;

  const supabase = createClient<Database>(
    SUPABASE_URL,
    SUPABASE_PUBLISHABLE_KEY,
    {
      global: {
        fetch: createSupabaseFetch(SUPABASE_PUBLISHABLE_KEY),
        headers: token
          ? {
              Authorization: `Bearer ${token}`,
            }
          : undefined,
      },
      auth: {
        storage: undefined,
        persistSession: false,
        autoRefreshToken: false,
      },
    },
  );

  let userId: string | undefined;
  let claims: any = {};

  if (token && token.split(".").length === 3) {
    try {
      const payloadJson = Buffer.from(token.split(".")[1], "base64").toString(
        "utf8",
      );
      const parsed = JSON.parse(payloadJson);
      if (parsed.iss?.includes("securetoken.google.com") || parsed.firebase) {
        userId = parsed.user_id || parsed.sub;
        claims = parsed;
      }
    } catch {
      // not JSON
    }

    if (!userId) {
      try {
        const { data, error } = await supabase.auth.getClaims(token);
        if (!error && data?.claims?.sub) {
          userId = data.claims.sub;
          claims = data.claims;
        }
      } catch {
        // ignore
      }
    }
  }

  // Graceful fallback for visitors / guest users so home screen always works
  if (!userId) {
    userId = "00000000-0000-0000-0000-000000000000";
    claims = { sub: userId, role: "guest" };
  }

  return next({
    context: {
      supabase,
      userId,
      claims,
    },
  });
});
